//! Shared helpers of the skin tests: synthetic resolvers, image files generated by our own
//! code, temporary skin trees and a warning counter. Nothing here comes from game data.

#![allow(dead_code)]

use std::path::Path;
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};

use tessera_ui::skin::LabelIndex;

/// A resolver with the given (label, key) pairs for art assets and elements.
pub fn resolver(arts: &[(&str, u32)], elements: &[(&str, u32)]) -> (LabelIndex, LabelIndex) {
    let mut a = LabelIndex::new();
    for (l, k) in arts {
        a.insert(*k, l);
    }
    let mut e = LabelIndex::new();
    for (l, k) in elements {
        e.insert(*k, l);
    }
    (a, e)
}

/// An uncompressed 32-bit TGA of `w` × `h` (type 2). `pixel(x, y)` gives the displayed
/// pixel as `0xAARRGGBB`; rows are written top-down (descriptor 0x28) or bottom-up (0x08).
pub fn tga32(w: u16, h: u16, top_down: bool, pixel: impl Fn(u32, u32) -> u32) -> Vec<u8> {
    let desc = if top_down { 0x28 } else { 0x08 };
    let mut out = vec![0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, 0];
    out.extend_from_slice(&w.to_le_bytes());
    out.extend_from_slice(&h.to_le_bytes());
    out.extend_from_slice(&[32, desc]);
    for file_row in 0..u32::from(h) {
        let y = if top_down {
            file_row
        } else {
            u32::from(h) - 1 - file_row
        };
        for x in 0..u32::from(w) {
            let p = pixel(x, y);
            out.extend_from_slice(&[p as u8, (p >> 8) as u8, (p >> 16) as u8, (p >> 24) as u8]);
        }
    }
    out
}

/// A TGA with one colour everywhere.
pub fn tga_solid(w: u16, h: u16, argb: u32) -> Vec<u8> {
    tga32(w, h, true, |_, _| argb)
}

/// A TGA header and raw pixel bytes of any depth (type 2 or 3), top-down.
pub fn tga_raw(w: u16, h: u16, depth: u8, image_type: u8, data: &[u8]) -> Vec<u8> {
    let mut out = vec![0, 0, image_type, 0, 0, 0, 0, 0, 0, 0, 0, 0];
    out.extend_from_slice(&w.to_le_bytes());
    out.extend_from_slice(&h.to_le_bytes());
    out.extend_from_slice(&[depth, 0x20]);
    out.extend_from_slice(data);
    out
}

/// A DDS file: magic, 124-byte header with the given fields, then `data`.
#[allow(clippy::too_many_arguments)]
pub fn dds(
    w: u32,
    h: u32,
    linear: u32,
    pf_flags: u32,
    fourcc: &[u8; 4],
    bits: u32,
    masks: [u32; 4],
    data: &[u8],
) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(b"DDS ");
    let mut header = [0u32; 31];
    header[0] = 124;
    header[1] = 0x1007;
    header[2] = h;
    header[3] = w;
    header[4] = linear;
    header[18] = 32;
    header[19] = pf_flags;
    header[20] = u32::from_le_bytes(*fourcc);
    header[21] = bits;
    header[22..26].copy_from_slice(&masks);
    for v in header {
        out.extend_from_slice(&v.to_le_bytes());
    }
    out.extend_from_slice(data);
    out
}

/// Writes `bytes` at `path`, creating its folders.
pub fn write(path: &Path, bytes: &[u8]) {
    if let Some(p) = path.parent() {
        std::fs::create_dir_all(p).unwrap();
    }
    std::fs::write(path, bytes).unwrap();
}

/// Counts `tracing` warning events while a closure runs.
#[derive(Default)]
pub struct WarnCounter {
    count: Arc<AtomicUsize>,
}

impl WarnCounter {
    /// Runs `f` with this counter as the thread's subscriber; returns `f`'s result and the
    /// number of warnings.
    pub fn run<T>(f: impl FnOnce() -> T) -> (T, usize) {
        let count = Arc::new(AtomicUsize::new(0));
        let sub = Counter {
            count: Arc::clone(&count),
        };
        let out = tracing::subscriber::with_default(sub, f);
        (out, count.load(Ordering::SeqCst))
    }
}

struct Counter {
    count: Arc<AtomicUsize>,
}

impl tracing::Subscriber for Counter {
    fn enabled(&self, _: &tracing::Metadata<'_>) -> bool {
        true
    }
    fn new_span(&self, _: &tracing::span::Attributes<'_>) -> tracing::span::Id {
        tracing::span::Id::from_u64(1)
    }
    fn record(&self, _: &tracing::span::Id, _: &tracing::span::Record<'_>) {}
    fn record_follows_from(&self, _: &tracing::span::Id, _: &tracing::span::Id) {}
    fn event(&self, event: &tracing::Event<'_>) {
        if *event.metadata().level() == tracing::Level::WARN {
            self.count.fetch_add(1, Ordering::SeqCst);
        }
    }
    fn enter(&self, _: &tracing::span::Id) {}
    fn exit(&self, _: &tracing::span::Id) {}
}
